package com.mindbridge.safety.review;  import static org.assertj.core.api.Assertions.assertThat; import static org.assertj.core.api.Assertions.assertThatThrownBy;  import java.time.OffsetDateTime; import java.util.UUID; import org.junit.jupiter.api.DisplayName; import org.junit.jupiter.api.Test;  /**  * Unit test for {@link ExpertReview} entity invariants. No Spring  * context, no DB — pure POJO behaviour (factory + getters + equality).  */ @DisplayName("ExpertReview entity") class ExpertReviewTest {      @Test     @DisplayName("create() requires all identity fields")     void createRejectsNulls() {         UUID id = UUID.randomUUID();         UUID eventId = UUID.randomUUID();         UUID reviewerId = UUID.randomUUID();          assertThatThrownBy(() -> ExpertReview.create(null, eventId, reviewerId,                 ExpertReviewDecision.NO_ACTION, null))                 .isInstanceOf(NullPointerException.class)                 .hasMessageContaining("id");         assertThatThrownBy(() -> ExpertReview.create(id, null, reviewerId,                 ExpertReviewDecision.NO_ACTION, null))                 .isInstanceOf(NullPointerException.class)                 .hasMessageContaining("safetyEventId");         assertThatThrownBy(() -> ExpertReview.create(id, eventId, null,                 ExpertReviewDecision.NO_ACTION, null))                 .isInstanceOf(NullPointerException.class)                 .hasMessageContaining("reviewerId");         assertThatThrownBy(() -> ExpertReview.create(id, eventId, reviewerId, null, null))                 .isInstanceOf(NullPointerException.class)                 .hasMessageContaining("decision");     }      @Test     @DisplayName("create() accepts null note (note is optional)")     void createAcceptsNullNote() {         ExpertReview r = ExpertReview.create(                 UUID.randomUUID(), UUID.randomUUID(), UUID.randomUUID(),                 ExpertReviewDecision.NO_ACTION, null);         assertThat(r.getNote()).isNull();     }      @Test     @DisplayName("create() accepts all 7 decision values")     void createAcceptsAllDecisions() {         UUID id = UUID.randomUUID();         UUID eventId = UUID.randomUUID();         UUID reviewerId = UUID.randomUUID();         for (ExpertReviewDecision d : ExpertReviewDecision.values()) {             ExpertReview r = ExpertReview.create(id, eventId, reviewerId, d, null);             assertThat(r.getDecision()).isEqualTo(d);         }     }      @Test     @DisplayName("equals/hashCode use id only")     void equalsById() {         UUID id = UUID.randomUUID();         UUID eventId = UUID.randomUUID();         UUID reviewerId = UUID.randomUUID();         ExpertReview a = ExpertReview.create(id, eventId, reviewerId,                 ExpertReviewDecision.NO_ACTION, null);         ExpertReview b = ExpertReview.create(id, eventId, reviewerId,                 ExpertReviewDecision.ESCALATE, "different");         assertThat(a).isEqualTo(b);         assertThat(a.hashCode()).isEqualTo(b.hashCode());     }      @Test     @DisplayName("two reviews with different ids are not equal")     void notEqualByDifferentId() {         ExpertReview a = ExpertReview.create(UUID.randomUUID(), UUID.randomUUID(),                 UUID.randomUUID(), ExpertReviewDecision.NO_ACTION, null);         ExpertReview b = ExpertReview.create(UUID.randomUUID(), UUID.randomUUID(),                 UUID.randomUUID(), ExpertReviewDecision.NO_ACTION, null);         assertThat(a).isNotEqualTo(b);     }      @Test     @DisplayName("Decision enum has the 7 documented values")     void decisionEnumShape() {         assertThat(ExpertReviewDecision.values()).containsExactly(                 ExpertReviewDecision.CONFIRM_RISK,                 ExpertReviewDecision.DOWNGRADE_RISK,                 ExpertReviewDecision.ESCALATE,                 ExpertReviewDecision.NO_ACTION,                 ExpertReviewDecision.CONTINUE_MONITORING,                 ExpertReviewDecision.REQUEST_FOLLOWUP,                 ExpertReviewDecision.DISMISS);     } }